package main
import("encoding/binary";"errors";"flag";"fmt";"io";"log";"net";"strconv";"sync";"time";"bytes";"os")
func read(r io.Reader,n int)([]byte,error){b:=make([]byte,n);_,e:=io.ReadFull(r,b);return b,e}
func addr(r io.Reader)([]byte,error){a,e:=read(r,1);if e!=nil{return nil,e};n:=0;switch a[0]{case 1:n=4;case 4:n=16;case 3:t,e:=read(r,1);if e!=nil{return nil,e};a=append(a,t...);n=int(t[0]);default:return nil,errors.New("bad address type")};b,e:=read(r,n+2);return append(a,b...),e}
func authenticate(c net.Conn,user,pass string)error{h,e:=read(c,2);if e!=nil{return e};if h[0]!=5{return errors.New("bad socks version")};m,e:=read(c,int(h[1]));if e!=nil{return e};want:=byte(0);if user!=""{want=2};ok:=false;for _,v:=range m{if v==want{ok=true}};if !ok{c.Write([]byte{5,255});return errors.New("auth method unavailable")};if _,e=c.Write([]byte{5,want});e!=nil{return e};if want==2{h,e=read(c,2);if e!=nil{return e};if h[0]!=1{return errors.New("auth version")};u,e:=read(c,int(h[1]));if e!=nil{return e};pLen,e:=read(c,1);if e!=nil{return e};p,e:=read(c,int(pLen[0]));if e!=nil{return e};if string(u)!=user||string(p)!=pass{c.Write([]byte{1,1});return errors.New("bad login")};_,e=c.Write([]byte{1,0});return e};return nil}
func authUp(c net.Conn,user,pass string)error{m:=byte(0);if user!=""{m=2};if _,e:=c.Write([]byte{5,1,m});e!=nil{return e};h,e:=read(c,2);if e!=nil{return e};if h[0]!=5||h[1]!=m{return errors.New("upstream auth method")};if m==2{if len(user)>255||len(pass)>255{return errors.New("credentials too long")};b:=append([]byte{1,byte(len(user))},[]byte(user)...);b=append(b,byte(len(pass)));b=append(b,[]byte(pass)...);if _,e=c.Write(b);e!=nil{return e};r,e:=read(c,2);if e!=nil{return e};if r[0]!=1||r[1]!=0{return errors.New("upstream credentials rejected")}};return nil}
func request(c net.Conn,cmd byte,dst []byte)([]byte,error){if _,e:=c.Write(append([]byte{5,cmd,0},dst...));e!=nil{return nil,e};h,e:=read(c,3);if e!=nil{return nil,e};if h[0]!=5||h[1]!=0{return nil,fmt.Errorf("upstream SOCKS failure %v",h)};return addr(c)}
func parseRelay(a []byte)(*net.UDPAddr,error){if len(a)<3{return nil,errors.New("short relay address")};host:="";switch a[0]{case 1:if len(a)!=7{return nil,errors.New("ipv4 length")};host=net.IP(a[1:5]).String();case 4:if len(a)!=19{return nil,errors.New("ipv6 length")};host=net.IP(a[1:17]).String();case 3:if len(a)!=int(a[1])+4{return nil,errors.New("domain length")};host=string(a[2:2+int(a[1])]);default:return nil,errors.New("address type")};if host=="0.0.0.0"||host=="::"{host="127.0.0.1"};return net.ResolveUDPAddr("udp",net.JoinHostPort(host,strconv.Itoa(int(binary.BigEndian.Uint16(a[len(a)-2:])))))}
func stream(a,b net.Conn){var w sync.WaitGroup;w.Add(2);go func(){defer w.Done();io.Copy(a,b);if c,ok:=a.(*net.TCPConn);ok{c.CloseWrite()}}();go func(){defer w.Done();io.Copy(b,a);if c,ok:=b.(*net.TCPConn);ok{c.CloseWrite()}}();w.Wait()}
func udpRelay(c,u net.Conn)error{remote,e:=request(u,3,[]byte{1,0,0,0,0,0,0});if e!=nil{return e};relay,e:=parseRelay(remote);if e!=nil{return e};udp,e:=net.DialUDP("udp",nil,relay);if e!=nil{return e};defer udp.Close();if _,e=c.Write([]byte{5,0,0,1,0,0,0,0,0,0});e!=nil{return e};c.SetDeadline(time.Time{});u.SetDeadline(time.Time{});log.Printf("[hevbridge] UDP relay established %s",relay);done:=make(chan struct{});var once sync.Once;stop:=func(){once.Do(func(){close(done);c.Close();udp.Close()})};defer stop()
go func(){b:=make([]byte,65535);for{n,e:=udp.Read(b);if e!=nil{stop();return};if n<10||b[0]!=0||b[1]!=0||b[2]!=0{continue};rd,e:=addr(bytes.NewReader(b[3:n]));if e!=nil{continue};head:=3+len(rd);if head>255||n<head{continue};payloadLen:=n-head;if payloadLen>65507{continue};h:=[]byte{byte(payloadLen>>8),byte(payloadLen),byte(head)};out:=append(h,rd...);out=append(out,b[head:n]...);if _,e=c.Write(out);e!=nil{stop();return}}}()
for{h,e:=read(c,3);if e!=nil{return e};n:=int(binary.BigEndian.Uint16(h[:2]));hl:=int(h[2]);if n>65507||hl<7{return errors.New("invalid Hev frame")};b,e:=read(c,hl-3+n);if e!=nil{return e};rd,e:=addr(bytes.NewReader(b));if e!=nil||len(rd)!=hl-3{return errors.New("invalid Hev address")};datagram:=append([]byte{0,0,0},b...);if _,e=udp.Write(datagram);e!=nil{return e}}}
func serve(c net.Conn,upstream,user,pass string)error{defer c.Close();c.SetDeadline(time.Now().Add(10*time.Second));if e:=authenticate(c,user,pass);e!=nil{return e};h,e:=read(c,3);if e!=nil{return e};if h[0]!=5||h[2]!=0{return errors.New("bad SOCKS request")};dst,e:=addr(c);if e!=nil{return e};if h[1]!=1&&h[1]!=5{c.Write([]byte{5,7,0,1,0,0,0,0,0,0});return fmt.Errorf("unsupported SOCKS command %d",h[1])};u,e:=net.DialTimeout("tcp",upstream,10*time.Second);if e!=nil{return e};defer u.Close();if e=authUp(u,user,pass);e!=nil{return e};if h[1]==5{return udpRelay(c,u)};_,e=request(u,1,dst);if e!=nil{return e};if _,e=c.Write([]byte{5,0,0,1,0,0,0,0,0,0});e!=nil{return e};c.SetDeadline(time.Time{});u.SetDeadline(time.Time{});stream(c,u);return nil}
func main(){listen:=flag.String("listen","0.0.0.0:1080","listen address");up:=flag.String("upstream","127.0.0.1:1081","sing-box proxy");user:=flag.String("user",os.Getenv("HEVBRIDGE_USERNAME"),"SOCKS username");pass:=flag.String("password",os.Getenv("HEVBRIDGE_PASSWORD"),"SOCKS password");flag.Parse();l,e:=net.Listen("tcp",*listen);if e!=nil{log.Fatal(e)};defer l.Close();log.Printf("[hevbridge] listening on %s; upstream %s",*listen,*up);for{c,e:=l.Accept();if e!=nil{log.Print(e);continue};go func(){if e:=serve(c,*up,*user,*pass);e!=nil&&!errors.Is(e,io.EOF){log.Printf("[hevbridge] %v",e)}}()}}
